using System.ComponentModel.DataAnnotations;
namespace Staybnb.Models;
public class RegisterViewModel { [Required,StringLength(100)] public string DisplayName {get;set;}=""; [Required,EmailAddress] public string Email {get;set;}=""; [Required,MinLength(8),DataType(DataType.Password)] public string Password {get;set;}=""; [Required,Compare(nameof(Password)),DataType(DataType.Password),Display(Name="Confirm password")] public string ConfirmPassword {get;set;}=""; }
public class LoginViewModel { [Required,EmailAddress] public string Email {get;set;}=""; [Required,DataType(DataType.Password)] public string Password {get;set;}=""; public bool RememberMe {get;set;} }
public class HostApplicationViewModel { [Required,StringLength(120)] public string Title {get;set;}=""; [Required,StringLength(3000)] public string Description {get;set;}=""; [Range(1,1000000)] public decimal PricePerNight {get;set;} [Range(0,100000)] public decimal CleaningFee {get;set;} public decimal ServiceFee {get;set;}=0; [Required] public string Address {get;set;}=""; [Required] public string City {get;set;}=""; public string PropertyType {get;set;}="Apartment"; [Range(1,30)] public int MaxGuests {get;set;}=2; [Required] public List<IFormFile> Images {get;set;}=[]; }
public class BookingCreateViewModel { public int PropertyId {get;set;} [Required,DataType(DataType.Date)] public DateTime CheckIn {get;set;} [Required,DataType(DataType.Date)] public DateTime CheckOut {get;set;} [Range(1,30)] public int Travelers {get;set;}=1; }
